const { withAppBuildGradle } = require('expo/config-plugins');

/** Marker so the injection is idempotent and easy to spot in the generated file. */
const MARKER = '// KendiHikayem: JS paketi debug APK icine gomulur';

/**
 * Embeds the JavaScript bundle into debug APKs.
 *
 * By default a debug build ships no JS at all: at launch it tries to pull the
 * bundle from the Metro dev server on localhost:8081. That is fine on a
 * developer's machine and useless for a downloadable test APK — on a phone the
 * fetch fails, React never mounts, and the app sits on the splash screen
 * forever with no error. That is exactly what happened here.
 *
 * HOW (and why NOT `bundleInDebug`):
 * `bundleInDebug = true` was the React Native < 0.71 knob, set through
 * `project.ext.react`. It does not exist on the modern Gradle plugin, and
 * setting it fails the build outright:
 *
 *   groovy.lang.MissingPropertyException: Could not set unknown property
 *   'bundleInDebug' for extension 'react' of type
 *   com.facebook.react.ReactExtension
 *
 * The modern equivalent is `debuggableVariants`. The React Gradle plugin skips
 * bundling for every variant named in that list, and it defaults to ["debug"].
 * Emptying the list therefore makes the debug variant bundle and pack the JS
 * exactly like a release build does, while keeping what makes a debug build
 * worth shipping to a tester:
 *   - no R8/ProGuard, so nothing is stripped or renamed;
 *   - dev support stays on, so a JS exception is shown ON SCREEN with a stack
 *     instead of killing the process with "uygulama sürekli olarak duruyor".
 *
 * android/ is generated by `expo prebuild` and gitignored, so this has to be a
 * config plugin — editing build.gradle by hand would not survive a build.
 */
module.exports = function withBundleInDebug(config) {
  return withAppBuildGradle(config, (cfg) => {
    const contents = cfg.modResults.contents;

    if (contents.includes(MARKER)) return cfg;

    const anchor = 'react {';
    const index = contents.indexOf(anchor);
    if (index === -1) {
      throw new Error(
        'withBundleInDebug: `react {` blogu app/build.gradle icinde bulunamadi. ' +
          'Expo sablonu degismis olabilir; eklenti guncellenmeli.',
      );
    }

    const insertAt = index + anchor.length;
    cfg.modResults.contents =
      contents.slice(0, insertAt) +
      `\n    ${MARKER};` +
      '\n    // aksi halde uygulama Metro sunucusunu arar ve splash ekraninda kalir.' +
      '\n    // Bos liste = "hicbir varyant debuggable degil" = debug de paketlenir.' +
      '\n    debuggableVariants = []' +
      contents.slice(insertAt);

    return cfg;
  });
};
